package configuration

import (
	"fmt"
	"strconv"
)

// Source resolves a configuration key to a raw value.
type Source func(key string) (value string, found bool)

// Config holds the application configuration values.
type Config struct {
	Port  int
	Name  string
	Debug bool
}

// Load reads configuration through the given Source and returns a Config.
func Load(source Source) (Config, error) {
	cfg := Config{
		Port:  8080,
		Name:  "helios",
		Debug: false,
	}

	if v, ok := source("HELIOS_PORT"); ok {
		n, err := strconv.Atoi(v)
		if err != nil {
			return Config{}, fmt.Errorf("HELIOS_PORT: %w", err)
		}
		if n < 1 || n > 65535 {
			return Config{}, fmt.Errorf("HELIOS_PORT: value %d out of range [1,65535]", n)
		}
		cfg.Port = n
	}

	if v, ok := source("HELIOS_NAME"); ok {
		if v == "" {
			return Config{}, fmt.Errorf("HELIOS_NAME: must not be empty")
		}
		cfg.Name = v
	}

	if v, ok := source("HELIOS_DEBUG"); ok {
		b, err := strconv.ParseBool(v)
		if err != nil {
			return Config{}, fmt.Errorf("HELIOS_DEBUG: %w", err)
		}
		cfg.Debug = b
	}

	return cfg, nil
}

package main

import (
	"fmt"
	"os"

	"example.helios/configuration"
)

func envSource(key string) (string, bool) {
	v, ok := os.LookupEnv(key)
	return v, ok
}

func main() {
	cfg, err := configuration.Load(envSource)
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: %v\n", err)
		os.Exit(1)
	}
	fmt.Printf("port=%d name=%s debug=%t\n", cfg.Port, cfg.Name, cfg.Debug)
}

package configuration

import (
	"errors"
	"strconv"
	"testing"
)

func src(m map[string]string) Source {
	return func(key string) (string, bool) {
		v, ok := m[key]
		return v, ok
	}
}

func TestDefaults(t *testing.T) {
	cfg, err := Load(src(nil))
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if cfg.Port != 8080 {
		t.Errorf("Port = %d, want 8080", cfg.Port)
	}
	if cfg.Name != "helios" {
		t.Errorf("Name = %q, want %q", cfg.Name, "helios")
	}
	if cfg.Debug != false {
		t.Errorf("Debug = %v, want false", cfg.Debug)
	}
}

func TestEmptySourceReturnsDefaults(t *testing.T) {
	cfg, err := Load(src(map[string]string{}))
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if cfg.Port != 8080 || cfg.Name != "helios" || cfg.Debug != false {
		t.Error("expected defaults with empty source")
	}
}

func TestPortParsing(t *testing.T) {
	tests := []struct {
		val     string
		want    int
		wantErr bool
	}{
		{"1", 1, false},
		{"8080", 8080, false},
		{"65535", 65535, false},
		{"0", 0, true},
		{"65536", 0, true},
		{"-1", 0, true},
		{"abc", 0, true},
		{"", 0, true},
	}
	for _, tt := range tests {
		cfg, err := Load(src(map[string]string{"HELIOS_PORT": tt.val}))
		if tt.wantErr {
			if err == nil {
				t.Errorf("HELIOS_PORT=%q: expected error, got %+v", tt.val, cfg)
			}
			continue
		}
		if err != nil {
			t.Errorf("HELIOS_PORT=%q: unexpected error: %v", tt.val, err)
		} else if cfg.Port != tt.want {
			t.Errorf("HELIOS_PORT=%q: Port=%d, want %d", tt.val, cfg.Port, tt.want)
		}
	}
}

func TestPortParseErrorIsPreserved(t *testing.T) {
	_, err := Load(src(map[string]string{"HELIOS_PORT": "not-a-number"}))
	if err == nil {
		t.Fatal("expected error")
	}
	var numErr *strconv.NumError
	if !errors.As(err, &numErr) {
		t.Errorf("expected *strconv.NumError to be reachable via errors.As, got %T", err)
	}
}

func TestNameValidation(t *testing.T) {
	cfg, err := Load(src(map[string]string{"HELIOS_NAME": "my-service"}))
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if cfg.Name != "my-service" {
		t.Errorf("Name = %q, want %q", cfg.Name, "my-service")
	}
}

func TestNameEmptyIsError(t *testing.T) {
	_, err := Load(src(map[string]string{"HELIOS_NAME": ""}))
	if err == nil {
		t.Fatal("expected error for empty HELIOS_NAME")
	}
}

func TestDebugParsing(t *testing.T) {
	tests := []struct {
		val     string
		want    bool
		wantErr bool
	}{
		{"true", true, false},
		{"1", true, false},
		{"false", false, false},
		{"0", false, false},
		{"t", true, false},
		{"f", false, false},
		{"TRUE", true, false},
		{"FALSE", false, false},
		{"yes", true, false},
		{"no", false, false},
		{"", false, true},
		{"bad", false, true},
	}
	for _, tt := range tests {
		cfg, err := Load(src(map[string]string{"HELIOS_DEBUG": tt.val}))
		if tt.wantErr {
			if err == nil {
				t.Errorf("HELIOS_DEBUG=%q: expected error", tt.val)
			}
			continue
		}
		if err != nil {
			t.Errorf("HELIOS_DEBUG=%q: unexpected error: %v", tt.val, err)
		} else if cfg.Debug != tt.want {
			t.Errorf("HELIOS_DEBUG=%q: Debug=%v, want %v", tt.val, cfg.Debug, tt.want)
		}
	}
}

func TestAllFieldsSet(t *testing.T) {
	cfg, err := Load(src(map[string]string{
		"HELIOS_PORT":  "9090",
		"HELIOS_NAME":  "production",
		"HELIOS_DEBUG": "true",
	}))
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if cfg.Port != 9090 {
		t.Errorf("Port = %d, want 9090", cfg.Port)
	}
	if cfg.Name != "production" {
		t.Errorf("Name = %q, want %q", cfg.Name, "production")
	}
	if cfg.Debug != true {
		t.Errorf("Debug = %v, want true", cfg.Debug)
	}
}

func TestSourceNotCalledForUnsetKeys(t *testing.T) {
	called := false
	cfg, err := Load(func(key string) (string, bool) {
		called = true
		return "", false
	})
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if called {
		t.Error("source was called even though no keys are configured")
	}
	if cfg.Port != 8080 || cfg.Name != "helios" || cfg.Debug != false {
		t.Error("expected defaults when source was never called")
	}
}

